-- 1. Create table announcements_announcement if not exists
CREATE TABLE IF NOT EXISTS "announcements_announcement" (
    "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "title" varchar(160) NOT NULL,
    "message" text NOT NULL DEFAULT '',
    "status" varchar(20) NOT NULL DEFAULT 'DRAFT',
    "audience" varchar(20) NOT NULL DEFAULT 'everyone',
    "event_date" date NULL,
    "publish_on" date NULL,
    "pinned" boolean NOT NULL DEFAULT false,
    "published_at" timestamp with time zone NULL,
    "archived_at" timestamp with time zone NULL,
    "created_at" timestamp with time zone NOT NULL DEFAULT NOW(),
    "updated_at" timestamp with time zone NOT NULL DEFAULT NOW(),
    "created_by_id" bigint NULL REFERENCES "accounts_user" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED
);

-- 2. Add event_date column if table already existed without it (Migration 0002)
ALTER TABLE "announcements_announcement" ADD COLUMN IF NOT EXISTS "event_date" date NULL;

-- 3. Create table announcements_announcement_recipients if not exists (M2M relation)
CREATE TABLE IF NOT EXISTS "announcements_announcement_recipients" (
    "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "announcement_id" bigint NOT NULL REFERENCES "announcements_announcement" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED
);

-- 4. Create indexes if not exists
CREATE INDEX IF NOT EXISTS "announce_status_idx" ON "announcements_announcement" ("status");
CREATE INDEX IF NOT EXISTS "announcements_announcement_created_by_id_79d7d337" ON "announcements_announcement" ("created_by_id");
CREATE INDEX IF NOT EXISTS "announcements_announcement_recipients_announcement_id_e9ea58d0" ON "announcements_announcement_recipients" ("announcement_id");
CREATE INDEX IF NOT EXISTS "announcements_announcement_recipients_user_id_00b2f252" ON "announcements_announcement_recipients" ("user_id");

DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'announcements_announceme_announcement_id_user_id_176f7fb2_uniq') THEN
        ALTER TABLE "announcements_announcement_recipients" ADD CONSTRAINT "announcements_announceme_announcement_id_user_id_176f7fb2_uniq" UNIQUE ("announcement_id", "user_id");
    END IF;
EXCEPTION
    WHEN duplicate_table OR duplicate_object THEN NULL;
END $$;

-- 5. Register migrations in django_migrations table so Django stays in sync
DO $$ BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'django_migrations') THEN
        INSERT INTO django_migrations (app, name, applied)
        SELECT 'announcements', '0001_initial', NOW()
        WHERE NOT EXISTS (SELECT 1 FROM django_migrations WHERE app = 'announcements' AND name = '0001_initial');

        INSERT INTO django_migrations (app, name, applied)
        SELECT 'announcements', '0002_announcement_event_date_alter_announcement_audience_and_more', NOW()
        WHERE NOT EXISTS (SELECT 1 FROM django_migrations WHERE app = 'announcements' AND name = '0002_announcement_event_date_alter_announcement_audience_and_more');
    END IF;
